import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import { BRAND } from "@/lib/brand";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
  inOutEnvelope,
} from "../motion";

export const fps = 25;
export const durationInFrames = 200;

const SCENE_DURATION = 200;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/Back_Dark.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

const DashboardGlyph: React.FC<{ size: number; progress: number }> = ({
  size,
  progress,
}) => {
  const bars = [0.45, 0.75, 0.55, 0.9];
  return (
    <svg width={size} height={size} viewBox="0 0 48 48" fill="none">
      {bars.map((h, i) => {
        const barProgress = interpolate(
          progress,
          [i * 0.15, 0.6 + i * 0.1],
          [0, 1],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );
        const barH = 28 * h * barProgress;
        return (
          <rect
            key={i}
            x={8 + i * 9}
            y={38 - barH}
            width={6}
            height={barH}
            fill={COLORS.orange}
            rx={1.5}
          />
        );
      })}
      <line
        x1="6"
        y1="40"
        x2="42"
        y2="40"
        stroke={COLORS.textMuted}
        strokeWidth={1.5}
        strokeLinecap="round"
        opacity={progress}
      />
    </svg>
  );
};

const PipelineGlyph: React.FC<{ size: number; progress: number }> = ({
  size,
  progress,
}) => {
  return (
    <svg width={size} height={size} viewBox="0 0 48 48" fill="none">
      {[0, 1, 2].map((i) => {
        const layerP = interpolate(
          progress,
          [i * 0.2, 0.6 + i * 0.15],
          [0, 1],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );
        return (
          <rect
            key={i}
            x={10}
            y={12 + i * 8}
            width={28}
            height={5}
            fill="none"
            stroke={COLORS.orange}
            strokeWidth={1.8}
            rx={1.5}
            opacity={layerP}
            strokeDasharray={70}
            strokeDashoffset={interpolate(layerP, [0, 1], [70, 0])}
          />
        );
      })}
      <path
        d="M 32 36 L 40 36 M 37 33 L 40 36 L 37 39"
        stroke={COLORS.orange}
        strokeWidth={1.8}
        strokeLinecap="round"
        strokeLinejoin="round"
        fill="none"
        opacity={interpolate(progress, [0.5, 1], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        })}
      />
    </svg>
  );
};

const AgentGlyph: React.FC<{ size: number; progress: number }> = ({
  size,
  progress,
}) => {
  const nodes = [
    { x: 24, y: 14 },
    { x: 12, y: 28 },
    { x: 36, y: 28 },
    { x: 24, y: 36 },
  ];
  return (
    <svg width={size} height={size} viewBox="0 0 48 48" fill="none">
      {[
        [0, 1],
        [0, 2],
        [1, 3],
        [2, 3],
        [0, 3],
      ].map(([a, b], i) => {
        const lp = interpolate(progress, [0.1 + i * 0.05, 0.7], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
        return (
          <line
            key={i}
            x1={nodes[a].x}
            y1={nodes[a].y}
            x2={nodes[b].x}
            y2={nodes[b].y}
            stroke={COLORS.orange}
            strokeWidth={1.2}
            opacity={lp * 0.7}
          />
        );
      })}
      {nodes.map((n, i) => {
        const np = interpolate(
          progress,
          [0.3 + i * 0.08, 0.8 + i * 0.05],
          [0, 1],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );
        return (
          <circle
            key={i}
            cx={n.x}
            cy={n.y}
            r={3 * np}
            fill={COLORS.orange}
          />
        );
      })}
    </svg>
  );
};

const MegaphoneGlyph: React.FC<{ size: number; progress: number }> = ({
  size,
  progress,
}) => {
  const drawP = interpolate(progress, [0, 0.6], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const wavesP = interpolate(progress, [0.5, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  return (
    <svg width={size} height={size} viewBox="0 0 48 48" fill="none">
      <path
        d="M 10 20 L 10 28 L 18 28 L 32 36 L 32 12 L 18 20 Z"
        stroke={COLORS.orange}
        strokeWidth={1.8}
        strokeLinejoin="round"
        fill="none"
        strokeDasharray={120}
        strokeDashoffset={interpolate(drawP, [0, 1], [120, 0])}
      />
      <path
        d="M 36 18 Q 40 24 36 30"
        stroke={COLORS.orange}
        strokeWidth={1.6}
        strokeLinecap="round"
        fill="none"
        opacity={wavesP}
      />
      <path
        d="M 40 14 Q 46 24 40 34"
        stroke={COLORS.orange}
        strokeWidth={1.4}
        strokeLinecap="round"
        fill="none"
        opacity={wavesP * 0.6}
      />
    </svg>
  );
};

const ContactGlyph: React.FC<{ size: number; progress: number }> = ({
  size,
  progress,
}) => {
  const cardP = interpolate(progress, [0, 0.5], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const detailP = interpolate(progress, [0.4, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  return (
    <svg width={size} height={size} viewBox="0 0 48 48" fill="none">
      <rect
        x={8}
        y={10}
        width={32}
        height={28}
        rx={3}
        stroke={COLORS.orange}
        strokeWidth={1.8}
        fill="none"
        strokeDasharray={120}
        strokeDashoffset={interpolate(cardP, [0, 1], [120, 0])}
      />
      <circle cx={18} cy={22} r={3.5 * detailP} fill={COLORS.orange} />
      <line
        x1="26"
        y1="20"
        x2="36"
        y2="20"
        stroke={COLORS.orange}
        strokeWidth={1.4}
        strokeLinecap="round"
        opacity={detailP}
      />
      <line
        x1="26"
        y1="24"
        x2="34"
        y2="24"
        stroke={COLORS.textMuted}
        strokeWidth={1.4}
        strokeLinecap="round"
        opacity={detailP}
      />
      <line
        x1="14"
        y1="31"
        x2="34"
        y2="31"
        stroke={COLORS.textMuted}
        strokeWidth={1.2}
        strokeLinecap="round"
        opacity={detailP * 0.7}
      />
    </svg>
  );
};

type Destination = {
  label: string;
  angle: number;
  Glyph: React.FC<{ size: number; progress: number }>;
  delay: number;
};

const DESTINATIONS: Destination[] = [
  {
    label: "Dashboards",
    angle: -Math.PI / 2 - 0.15,
    Glyph: DashboardGlyph,
    delay: 25,
  },
  {
    label: "Data pipelines",
    angle: -Math.PI / 2 + (2 * Math.PI) / 5,
    Glyph: PipelineGlyph,
    delay: 50,
  },
  {
    label: "AI agents",
    angle: -Math.PI / 2 + (4 * Math.PI) / 5,
    Glyph: AgentGlyph,
    delay: 75,
  },
  {
    label: "Marketing tools",
    angle: -Math.PI / 2 + (6 * Math.PI) / 5,
    Glyph: MegaphoneGlyph,
    delay: 100,
  },
  {
    label: "CRM enrichment",
    angle: -Math.PI / 2 + (8 * Math.PI) / 5,
    Glyph: ContactGlyph,
    delay: 125,
  },
];

const ConnectionScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  const centralIn = springIn(frame, vfps, 4, "SNAPPY");
  const centralBreathe = ambientDrift(frame, 2, 90, "central");
  const compositionDriftX = ambientDrift(frame, 4, 140, "comp-x");
  const compositionDriftY = ambientDrift(frame, 3, 110, "comp-y");

  const cx = width / 2;
  const cy = height / 2 + base * 0.01;
  const radius = base * 0.4;
  const centralSize = base * 0.36;
  const destNodeSize = base * 0.095;
  const glyphSize = destNodeSize * 0.62;
  const labelSize = base * 0.018;

  const pulseStart = 150;
  const pulsePhase = interpolate(
    frame,
    [pulseStart, SCENE_DURATION],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const centralEdge = centralSize * 0.45;

  const connections = DESTINATIONS.map((dest) => {
    const dxFull = Math.cos(dest.angle) * radius;
    const dyFull = Math.sin(dest.angle) * radius;
    const startX = cx + Math.cos(dest.angle) * centralEdge;
    const startY = cy + Math.sin(dest.angle) * centralEdge;
    const endX = cx + dxFull;
    const endY = cy + dyFull;
    const lineProgress = springIn(frame, vfps, dest.delay, "LIQUID");
    return {
      dest,
      startX,
      startY,
      endX,
      endY,
      dxFull,
      dyFull,
      lineProgress,
    };
  });

  return (
    <AbsoluteFill>
      <Background />

      <div
        style={{
          position: "absolute",
          inset: 0,
          transform: `translate(${compositionDriftX}px, ${compositionDriftY}px)`,
        }}
      >
        <svg
          width={width}
          height={height}
          style={{ position: "absolute", inset: 0, pointerEvents: "none" }}
        >
          {connections.map((c, i) => {
            const lineX = c.startX + (c.endX - c.startX) * c.lineProgress;
            const lineY = c.startY + (c.endY - c.startY) * c.lineProgress;
            const pulseLocal = interpolate(
              (pulsePhase + i * 0.18) % 1,
              [0, 0.5, 1],
              [0, 1, 0]
            );
            return (
              <React.Fragment key={i}>
                <line
                  x1={c.startX}
                  y1={c.startY}
                  x2={lineX}
                  y2={lineY}
                  stroke={COLORS.orange}
                  strokeWidth={1.5}
                  strokeLinecap="round"
                  opacity={0.55}
                />
                {c.lineProgress > 0.95 && (
                  <circle
                    cx={
                      c.startX +
                      (c.endX - c.startX) * (0.3 + pulseLocal * 0.6)
                    }
                    cy={
                      c.startY +
                      (c.endY - c.startY) * (0.3 + pulseLocal * 0.6)
                    }
                    r={base * 0.005}
                    fill={COLORS.orange}
                    opacity={pulseLocal}
                  />
                )}
              </React.Fragment>
            );
          })}
        </svg>

        {/* Central node — glow removed, just the asset itself */}
        <div
          style={{
            position: "absolute",
            left: cx,
            top: cy,
            width: centralSize,
            height: centralSize,
            transform: `translate(-50%, -50%) translateY(${centralBreathe}px) scale(${interpolate(centralIn, [0, 1], [0, 1])})`,
            opacity: centralIn,
          }}
        >
          <Img
            src={staticFile("assets/other/IG Actor.png")}
            style={{
              position: "absolute",
              inset: 0,
              width: "100%",
              height: "100%",
              objectFit: "contain",
            }}
          />
        </div>

        {DESTINATIONS.map((dest, i) => {
          const dx = Math.cos(dest.angle) * radius;
          const dy = Math.sin(dest.angle) * radius;
          const nodeX = cx + dx;
          const nodeY = cy + dy;

          const nodeIn = springIn(frame, vfps, dest.delay + 14, "ELASTIC");
          const glyphProgress = springIn(frame, vfps, dest.delay + 18, "LIQUID");

          const nodeDriftX = ambientDrift(frame, 1.5, 80 + i * 7, `node-x-${i}`);
          const nodeDriftY = ambientDrift(frame, 1.5, 95 + i * 6, `node-y-${i}`);

          const labelGap = base * 0.018;
          const labelDX = 0;
          const labelDY = destNodeSize / 2 + labelGap;

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: nodeX,
                top: nodeY,
                width: destNodeSize,
                height: destNodeSize,
                transform: `translate(-50%, -50%) translate(${nodeDriftX}px, ${nodeDriftY}px)`,
              }}
            >
              {/* Destination node — glow removed, just the card + glyph */}
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  transform: `scale(${interpolate(nodeIn, [0, 1], [0, 1])})`,
                  opacity: nodeIn,
                  backgroundColor: "rgba(255,255,255,0.05)",
                  border: `1px solid ${COLORS.border}`,
                  borderRadius: destNodeSize * 0.2,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <dest.Glyph size={glyphSize} progress={glyphProgress} />
              </div>

              <div
                style={{
                  position: "absolute",
                  left: "50%",
                  top: "50%",
                  transform: `translate(-50%, 0) translate(${labelDX}px, ${labelDY}px)`,
                  whiteSpace: "nowrap",
                  fontFamily: "Inter, sans-serif",
                  fontSize: labelSize,
                  fontWeight: 500,
                  color: COLORS.textMuted,
                  letterSpacing: "0.12em",
                  textTransform: "uppercase",
                  opacity: interpolate(nodeIn, [0, 0.6, 1], [0, 0, 1]),
                  textAlign: "center",
                }}
              >
                {dest.label}
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={SCENE_DURATION}>
        <ConnectionScene />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export { MainComposition };
export default MainComposition;
